export class ParserExit extends Error {
  constructor(code, stdout = '', stderr = '') {
    super(`Parser exited with code ${code}`);
    this.code = code;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

function basename(pathLike) {
  const parts = String(pathLike || '').split(/[\\/]/);
  return parts[parts.length - 1] || 'test10.mjs';
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A --b B\n`;
}

function help(programName) {
  return `${usage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

function errorOutput(programName, message) {
  return `${usage(programName)}${programName}: error: ${message}\n`;
}

function isOptionToken(token) {
  return token.startsWith('-') && token !== '-';
}

function takeUnknownArgument(tokens, index, extras) {
  extras.push(tokens[index]);

  if (index + 1 < tokens.length && !isOptionToken(tokens[index + 1])) {
    extras.push(tokens[index + 1]);
    return index + 1;
  }

  return index;
}

function parserError(programName, message) {
  throw new ParserExit(2, '', errorOutput(programName, message));
}

export function parseTest10Arguments(argv = process.argv) {
  const programName = basename(argv[1]);
  const tokens = argv.slice(2);
  const values = { a: undefined, b: undefined };
  const extras = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '-h' || token === '--help') {
      throw new ParserExit(0, help(programName), '');
    }

    if (token.startsWith('--help=')) {
      parserError(programName, `argument -h/--help: ignored explicit argument '${token.slice('--help='.length)}'`);
    }

    if (token.startsWith('-h') && token !== '-h') {
      parserError(programName, `argument -h/--help: ignored explicit argument '${token.slice(2)}'`);
    }

    if (token === '--') {
      extras.push(...tokens.slice(index + 1));
      break;
    }

    if (token === '--a' || token === '--b') {
      const destination = token.slice(2);
      const nextToken = tokens[index + 1];

      if (nextToken === undefined || isOptionToken(nextToken)) {
        parserError(programName, `argument ${token}: expected one argument`);
      }

      values[destination] = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      values.a = token.slice('--a='.length);
      continue;
    }

    if (token.startsWith('--b=')) {
      values.b = token.slice('--b='.length);
      continue;
    }

    if (token.startsWith('-')) {
      index = takeUnknownArgument(tokens, index, extras);
      continue;
    }

    extras.push(token);
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    parserError(programName, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    parserError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

